+static zend_generator_node *zend_generator_search_multi_children_node(zend_generator_node *node)
+{
+    /*
+     * Be defensive here: the tree can contain freed nodes during generator
+     * lifecycle changes (e.g. during yield from). Accessing a freed object's
+     * fields would lead to a use-after-free, which is exactly what the
+     * ASAN report is pointing at.
+     *
+     * If we encounter NULL pointers while traversing or if the current node is
+     * NULL, bail out gracefully by returning NULL. This keeps the traversal
+     * safe even in the presence of concurrent frees of generator structures.
+     */
+    if (!node) {
+        return NULL;
+    }
+    while (node->children == 1) {
+        /* Validate the single-child path before dereferencing */
+        if (node->child.single.child == NULL) {
+            return NULL;
+        }
+        node = &node->child.single.child->node;
+        if (!node) {
+            return NULL;
+        }
+    }
+    return (node && node->children > 1) ? node : NULL;
+}
